CREATE TABLE IF NOT EXISTS users (id CHAR(36) PRIMARY KEY, email VARCHAR(255) NOT NULL UNIQUE, password_hash VARCHAR(255) NOT NULL, role ENUM('admin','editor') NOT NULL DEFAULT 'admin', created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS projects (id CHAR(64) PRIMARY KEY, title_ru VARCHAR(255) NOT NULL, title_en VARCHAR(255) NOT NULL, category VARCHAR(64) NOT NULL, year SMALLINT NOT NULL, services JSON NOT NULL, status ENUM('draft','published','archived') NOT NULL DEFAULT 'draft', featured BOOLEAN NOT NULL DEFAULT FALSE, blocks JSON NOT NULL DEFAULT (JSON_ARRAY()), created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS enquiries (id CHAR(36) PRIMARY KEY, name VARCHAR(255) NOT NULL, company VARCHAR(255), email VARCHAR(255) NOT NULL, project_type VARCHAR(64), budget VARCHAR(128), deadline DATE, message TEXT NOT NULL, status ENUM('new','contacted','in_discussion','accepted','declined') NOT NULL DEFAULT 'new', created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP);
